begin;
-- Test-only grant mirrors the deployed Data API table grant; RLS remains enabled.
grant select on public.letters to authenticated;
do $$ declare a uuid:='a0000000-0000-0000-0000-000000000005'; l uuid;other uuid;before_hash text;begin l:=test_support.draft(a);other:=test_support.draft(a);perform set_config('request.jwt.claim.sub',a::text,true);assert app.can_read_letter_for(a,l);select md5(to_jsonb(x)::text) into before_hash from letters x where id=l;insert into app.removed_beta_letters(letter_id,reason) values(l,'Fixture: explicit beta cleanup');assert not app.can_read_letter_for(a,l);assert app.can_read_letter_for(a,other);assert (select md5(to_jsonb(x)::text) from letters x where id=l)=before_hash;perform set_config('test.removed.letter',l::text,true);perform set_config('test.visible.letter',other::text,true);end $$;set role authenticated;do $$ begin assert not exists(select 1 from letters where id=current_setting('test.removed.letter')::uuid);assert exists(select 1 from letters where id=current_setting('test.visible.letter')::uuid);assert not exists(select 1 from jsonb_array_elements(get_dashboard_letter_activity()) e where e->>'letter_id'=current_setting('test.removed.letter'));end $$;reset role;
rollback;
